    "description": "弹钢琴，周杰伦的花海，晴天，对照数字简谱按下琴键。骑电动车，要手控推动电动车往前走。买了好多书，中国地理，巧克力百科全书，皮肤病诊疗手册，高考数学，高考物理，清华大学微积分课程，太平御览，唐律疏议，韩愈全集，DK科学百科，但丁神曲，荷马史诗，万国衣冠拜冕旒，轻轻松松养黄粉虫，蔬菜种植技术，咬合修复。骑自行车，练习，在大操场。商贩卖砵仔糕，冰粉，炸串，鸡腿，面，鸟，龟，兔子，豚鼠，小鸡，仓鼠。摆摊做漆画，绘画扇子。卖棉花糖，糖葫芦。弹钢琴…",
