    "title": "古特雷斯：对哥伦比亚地震造成人员伤亡感到“悲痛”",
    "link": "http://www.news.cn/20260812/ce78c3fe46db435199c36752f66d18f4/c.html",
    "pub_date": "2026-08-12 06:46:44",
    "author": "尚绪谦",
    "description": "新华社联合国8月11日电（记者尚绪谦）联合国秘书长古特雷斯11日通过副发言人哈克发表声明表示，对哥伦比亚地震造成人员伤亡感到“悲痛”。 声明说，联合国与哥伦比亚当局保持密切接触，正在为哥政府主导的救灾行动提供帮助。 哥伦比亚全国首府协会11日发布的最新统计显示，10日在该国西部发生的7.4级强震已造成188人死亡、1677人受伤。",
    "content": "新华社联合国8月11日电（记者尚绪谦）联合国秘书长古特雷斯11日通过副发言人哈克发表声明表示，对哥伦比亚地震造成人员伤亡感到“悲痛”。 声明说，联合国与哥伦比亚当局保持密切接触，正在为哥政府主导的救灾行动提供帮助。 哥伦比亚全国首府协会11日发布的最新统计显示，10日在该国西部发生的7.4级强震已造成188人死亡、1677人受伤。"
