    "title": "伊拉克谴责哥伦比亚承认以色列对戈兰高地“主权”",
    "link": "http://www.news.cn/20260812/bf59224725ef45d8900642cc52ba25bd/c.html",
    "pub_date": "2026-08-12 03:50:13",
    "author": "李军",
    "description": "新华社巴格达8月11日电（记者李军）伊拉克外交部11日发表声明，强烈谴责哥伦比亚承认以色列对被占领的戈兰高地拥有“主权”的决定。 声明强调，戈兰高地是被占领的叙利亚领土，任何一方都无权改变其法律地位，或赋予占领方任何缺乏依据的合法性。哥伦比亚的这一决定不具备任何法律效力，也无法改变“戈兰高地是叙利亚领土不可分割的一部分”这一事实。 伊拉克外交部指出，承认占领国对被占领土拥有“主权”开创了危险先例，破坏国际法原则和《联合国宪章》。 声明重…",
    "content": "新华社巴格达8月11日电（记者李军）伊拉克外交部11日发表声明，强烈谴责哥伦比亚承认以色列对被占领的戈兰高地拥有“主权”的决定。 声明强调，戈兰高地是被占领的叙利亚领土，任何一方都无权改变其法律地位，或赋予占领方任何缺乏依据的合法性。哥伦比亚的这一决定不具备任何法律效力，也无法改变“戈兰高地是叙利亚领土不可分割的一部分”这一事实。 伊拉克外交部指出，承认占领国对被占领土拥有“主权”开创了危险先例，破坏国际法原则和《联合国宪章》。 声明重申，伊拉克完全支持叙利亚维护国家主权和领土完整。 右翼的哥伦比亚新政府10日宣布…"
