    "description": "新华社纽约8月11日电 国际油价11日上涨。 截至当天收盘，纽约商品交易所9月交货的轻质原油期货价格上涨1.07美元，收于每桶83.20美元，涨幅为1.3%；10月交货的伦敦布伦特原油期货价格上涨1.19美元，收于每桶88.91美元，涨幅为1.36%。",
