    "content": "新华社布达佩斯8月11日电（记者刘艺炜）匈牙利新当选总统鲍卡·安德拉什11日在国会表决后的演说中表示，重建与国际盟友的伙伴关系将成为其总统任期内的重要任务。 匈牙利国会11日经过投票表决，选举最高法院前院长鲍卡为新任总统。鲍卡在随后的演说中说，匈牙利近年来同一些国际盟友的关系有所恶化，重建这些伙伴关系将成为其任内的重要任务。 鲍卡还呼吁调查过去的滥用职权行为，并审查公共资金的使用。他还表示，将在政治上保持中立，正视政治分歧，同时维护宪法确立的权力制衡。 匈牙利总统由国会选举产生，任期5年。根据宪法规定，鲍卡将于当选…"
