    "description": "新华社日内瓦8月11日电（记者王其冰）中国裁军事务大使李驰江11日在日内瓦裁军谈判会议（简称裁谈会）上严正驳斥美国代表所谓“弹道导弹发射通报”涉华共同发言，强调中国正当合理的国防现代化建设不容置疑，中方提前通报导弹发射的善意举措不应被地缘政治算计所绑架；中方坚决反对个别国家滥用裁谈会平台搞政治操弄。 在当天举行的裁谈会全体会议上，美国等国发表所谓“弹道导弹发射通报”共同发言，无端指责中国7月进行的潜射洲际弹道导弹试射。李驰江发言予以严正…",
    "content": "新华社日内瓦8月11日电（记者王其冰）中国裁军事务大使李驰江11日在日内瓦裁军谈判会议（简称裁谈会）上严正驳斥美国代表所谓“弹道导弹发射通报”涉华共同发言，强调中国正当合理的国防现代化建设不容置疑，中方提前通报导弹发射的善意举措不应被地缘政治算计所绑架；中方坚决反对个别国家滥用裁谈会平台搞政治操弄。 在当天举行的裁谈会全体会议上，美国等国发表所谓“弹道导弹发射通报”共同发言，无端指责中国7月进行的潜射洲际弹道导弹试射。李驰江发言予以严正驳斥，阐明中方立场。 李驰江强调，中方坚决反对个别国家滥用裁谈会平台搞政治操弄。…"
