    "description": "台风“白海豚”8月9日两次登陆浙江后，10日13时离开浙江，开始北上西进。 中央气象台11日17时对台风“白海豚”停止编号，18时解除台风蓝色预警。但是受“白海豚”残余系统和冷空气共同影响，预计11至15日，河南等十多个省份有暴雨或大暴雨，豫鲁皖部分地区有特大暴雨。 各地各部门多措并举筑牢防汛防台风安全堤坝，坚决维护人民群众生命财产安全和社会大局稳定。 综合新华社记者报道 编导：于跃 新华社音视频部制作",
    "content": "台风“白海豚”8月9日两次登陆浙江后，10日13时离开浙江，开始北上西进。 中央气象台11日17时对台风“白海豚”停止编号，18时解除台风蓝色预警。但是受“白海豚”残余系统和冷空气共同影响，预计11至15日，河南等十多个省份有暴雨或大暴雨，豫鲁皖部分地区有特大暴雨。 各地各部门多措并举筑牢防汛防台风安全堤坝，坚决维护人民群众生命财产安全和社会大局稳定。 综合新华社记者报道 编导：于跃 新华社音视频部制作"
