    "description": "8月11日晚，广东揭西县河婆街道办事处发布情况通告，11日16时许，该街道辖区发生一起人员跳桥突发事件。接报后，党政立即组织应急救援力量赶赴现场开展救援工作。目前，涉溺水2名人员（均为男性，河婆人）遗体已搜救打捞上岸，无生命迹象。请广大市民群众不信谣、不传谣、不造谣、不拍摄，不传播相关视频、图片，尊重逝者，自觉维护良好网络环境和社会秩序。",
