    "content": "新华社北京8月11日电（记者魏弘毅）记者从水利部了解到，水利部于11日22时30分对北京、天津启动洪水防御Ⅳ级应急响应，并派出2个工作组赴北京、天津暴雨洪水防御一线协助指导。 据预报，8月11日夜间至13日，受台风“白海豚”残留云系和冷空气南下共同影响，北京、天津将出现强降水过程，以中到大雨为主，其中北京西南部、天津北部局地有暴雨到大暴雨；北京永定河、琉璃河、小清河，天津蓟运河将出现涨水过程，暴雨区内山洪灾害和中小河流洪水风险高。 为应对汛情，水利部督促指导地方水利部门密切监视台风“白海豚”残留云系影响态势，强化雨…"
