    "content": "之前 0.5.0 主要解决的是 Connect：让 agent-browser 、Browser Use 、Playwright CLI 接入日常使用的 Chrome / Edge 。0.10.0 又把另一条常见路径补完整了：直接用浏览器登录态请求已知 URL 。 现在 Panerelay 有三个比较明确的入口： Fetch ：对已知 HTTP(S) URL 发请求，复用浏览器中的登录状态；不导航页面、不读取 DOM ，也不会把 Cookie 返回给 Agent 。 Connect ：把自动化工具接到用户明确授权的…"
