    "description": "微软据报道大幅上涨了 PC OEM 厂商的 Windows 11 授权费。价格上涨于 7 月生效，平均上涨了 7% 至 10%。过去 Windows OEM 授权费上涨通常是个位数，这次上涨幅度更大。具体涨幅将基于 PC 处理器而存在差异，高端 CPU 系统需要支付不同的价格。微软此举无疑是雪上加霜，PC 市场已因内存和存储器涨价而苦苦挣扎。",
    "content": "微软据报道大幅上涨了 PC OEM 厂商的 Windows 11 授权费。价格上涨于 7 月生效，平均上涨了 7% 至 10%。过去 Windows OEM 授权费上涨通常是个位数，这次上涨幅度更大。具体涨幅将基于 PC 处理器而存在差异，高端 CPU 系统需要支付不同的价格。微软此举无疑是雪上加霜，PC 市场已因内存和存储器涨价而苦苦挣扎。"
