    "content": "新华社北京8月11日电 美国企业家、电动汽车制造商特斯拉公司首席执行官埃隆·马斯克11日在社交媒体上写道：“中国太棒了。我强烈推荐大家去看看。” 在社交媒体平台X上一条讨论特斯拉在华业务的帖子下，马斯克作上述评论。 马斯克的母亲梅耶·马斯克随后引用马斯克的这条帖文写道：“我同意。（中国的）每个城市都有其独特魅力，有不同的文化景点可以参观。建筑物和街道干净整洁，维护良好。同时，人们彬彬有礼、勤劳且尊重他人。我（在中国）感到安全，所以很享受去中国（旅行）。” 近期，美国皮尤研究中心等机构的调查显示，国际民众对中国的好感…"
