    "content": "今天收到了 OpenAI 赠送的 6 个月 Pro 20x 额度，为了回馈开源社区，把我一个月前用来练习复述能力的小工具开源了： https://github.com/kingname/retelling 它的功能很简单：你上传一段音频，它会自动帮你切成几个适合练习的片段。你先听一遍，然后用自己的话复述出来。复述完成以后，AI 会把你的录音和原文进行对比，告诉你哪些地方说对了，哪些地方漏掉了，哪些地方表达结构还有问题。 听起来好像只是一个普通的 AI 应用，但我做它的原因，是因为我发现很多人在练听力、练表达、准备面…"
