    "description": "11/08/2026 - 16:13 据毎日新聞 8月11日引述多名相关人士10日透露，数名在中国境内设有分支机构的日本企业社长等日本公民，因涉及含稀土元素的军民两用产品等对日出口管制问题，被中方扣留。针对日资企业的突击检查及对企业相关人员的问询也频频发生。在被扣留的日本公民中，有人竟是为配合中国当局的问询入境后遭到扣留的。 该报道说，事发在5月中国辽宁省大连市一家大型重电制造商集团的两名日本员工，因涉嫌携带稀土相关产品出境而被中方扣留…",
    "content": "11/08/2026 - 16:13 据毎日新聞 8月11日引述多名相关人士10日透露，数名在中国境内设有分支机构的日本企业社长等日本公民，因涉及含稀土元素的军民两用产品等对日出口管制问题，被中方扣留。针对日资企业的突击检查及对企业相关人员的问询也频频发生。在被扣留的日本公民中，有人竟是为配合中国当局的问询入境后遭到扣留的。 该报道说，事发在5月中国辽宁省大连市一家大型重电制造商集团的两名日本员工，因涉嫌携带稀土相关产品出境而被中方扣留事件前后。日本政府已向日本企业相关人员发出警示，要求若接到中国当局的询问等情况，…"
