    "author": "",
    "description": "中新网北京8月11日电(记者 王珊珊 高萌)最近，行业协会们迎来一波“大师摘牌潮”。贵州遵义市酒业协会发布了一则公告，表示根据有关要求，决定撤销该协会“中国酱香酒酿酒大师”等相关称号，此前发布的有关通知、公告、公示都废止，不能再用“中国酱香酒酿酒大师”的称号开展任何活动或宣传。",
    "content": "中新网北京8月11日电(记者 王珊珊 高萌)最近，行业协会们迎来一波“大师摘牌潮”。贵州遵义市酒业协会发布了一则公告，表示根据有关要求，决定撤销该协会“中国酱香酒酿酒大师”等相关称号，此前发布的有关通知、公告、公示都废止，不能再用“中国酱香酒酿酒大师”的称号开展任何活动或宣传。"
