    "description": "新华社开罗8月11日电（记者张健 姚兵）埃及卫生和人口部11日发表声明说，埃及东北部伊斯梅利亚省当天发生一起皮卡车翻车事故，造成至少15人死亡、32人受伤。 目前，伤者已被送往附近医院接受治疗。埃及卫生和人口部长加法尔要求为伤者提供医疗救治，并持续监测伤者病情。 声明说，伤亡数据为初步统计，仍在继续核实和完善。",
    "content": "新华社开罗8月11日电（记者张健 姚兵）埃及卫生和人口部11日发表声明说，埃及东北部伊斯梅利亚省当天发生一起皮卡车翻车事故，造成至少15人死亡、32人受伤。 目前，伤者已被送往附近医院接受治疗。埃及卫生和人口部长加法尔要求为伤者提供医疗救治，并持续监测伤者病情。 声明说，伤亡数据为初步统计，仍在继续核实和完善。"
