    "title": "三大洲际足联齐声讨！世界杯“私有化”提案搁浅，但各方博弈远未结束",
    "link": "https://www.chinanews.com.cn/ty/2026/08-11/10676035.shtml",
    "pub_date": "2026-08-11 21:50:44",
    "author": "",
    "description": "近日，国际足联主席因凡蒂诺主推的一项有关出售世界杯商业权益股份的提案持续引发热议。欧洲足联、亚洲足联和中北美洲及加勒比海地区足联8月10日发表联合公开信，批评这一提案是一次“严重的判断失误”。",
