    "content": "新华社科威特城8月11日电（记者尹炣）亚丁消息：也门一名军方人士11日称，也门政府军与胡塞武装当天在该国东北部的马里卜省交火，造成至少8名胡塞武装人员和3名政府军士兵死亡。 这一匿名的当地军方人士告诉新华社记者，双方在该省首府马里卜市附近的阵地展开了激烈交锋。政府军摧毁了位于马里卜市以西的一处胡塞武装通信站和导弹发射平台。 截至目前，胡塞武装尚未就此次交火发表评论。 马里卜省是政府军的关键据点，也是也门主要的石油和天然气生产地。也门胡塞武装曾多次试图向该省首府推进，并曾与政府军在此激烈交战。 2014年9月，胡塞武…"
