    "content": "新华社布达佩斯8月11日电（记者刘艺炜）匈牙利国会11日经过投票表决，选举前最高法院院长鲍卡·安德拉什为新任总统。 8月11日，在匈牙利布达佩斯，鲍卡·安德拉什抵达国会总统选举现场。新华社发（若尔瑙伊·彼得摄） 现年73岁的鲍卡由执政党蒂萨党提名，是此次选举唯一候选人，在无记名投票中获得140票，获三分之二以上议员支持。 公开资料显示，鲍卡于1991年至2008年担任欧洲人权法院法官，2009年起担任匈牙利最高法院院长。2011年，因公开批评当时青民盟政府推行的司法改革，其任期被提前终止，随后他继续在最高法院担任法…"
