    "content": "新华社乌鲁木齐8月11日电（记者杨林）记者11日从新疆维吾尔自治区人大常委会新闻发布会获悉，针对棉花产业高质量发展制定的地方性法规《新疆维吾尔自治区棉花质量促进条例》已于7月1日正式施行。 新疆维吾尔自治区人大常委会副秘书长、新闻发言人麦丽燕·司马义介绍，条例共六章37条，覆盖棉花种植、采收、收购、加工、销售、承储全产业链的质量提升，将公证检验、目标价格政策、在库公检、全链条质量追溯等有效做法上升为法规制度，对于提升新疆棉花质量水平、带动各族群众增收致富、维护棉纺织产业链供应链安全稳定具有重大意义。 据悉，新疆是我…"
