    "category": "国外",
    "title": "泽连斯基：莫斯科昨夜致命轰炸用了朝鲜弹道导弹 - RFI - 法国国际广播电台",
    "link": "https://www.rfi.fr/cn/%E5%9B%BD%E9%99%85/20260811-%E6%B3%BD%E8%BF%9E%E6%96%AF%E5%9F%BA-%E8%8E%AB%E6%96%AF%E7%A7%91%E6%98%A8%E5%A4%9C%E8%87%B4%E5%91%BD%E8%BD%B0%E7%82%B8%E7%94%A8%E4%BA%86%E6%9C%9D%E9%B2%9C%E5%BC%B9%E9%81%93%E5%AF%BC%E5%BC%B9",
    "pub_date": "2026-08-11 21:15:03",
